package validation
import("fmt";"strings"; collectorv1 "github.com/h66rogi/rogi-collector/proto/gen/collector/v1")
const MaxNativeBalloonCount int64 = 9007199254740991
func Donation(v *collectorv1.DonationEvent)error{if v==nil{return fmt.Errorf("donation required")};if v.GetNativeBalloonCount()<1||v.GetNativeBalloonCount()>MaxNativeBalloonCount{return fmt.Errorf("native_balloon_count outside positive JS safe integer range")};if v.GetObservedAt()==nil||v.GetObservedAt().CheckValid()!=nil{return fmt.Errorf("valid observed_at required")};if strings.TrimSpace(v.GetSchemaVersion())==""||v.GetEventType()!="donation"||strings.TrimSpace(v.GetEventId())==""||strings.TrimSpace(v.GetChannelId())==""||v.GetPlatform()!=collectorv1.Platform_PLATFORM_SOOP||strings.TrimSpace(v.GetPlatformChannelId())==""||v.GetNativeCurrency()!=collectorv1.NativeCurrency_NATIVE_CURRENCY_SOOP_BALLOON||strings.TrimSpace(v.GetDonationKind())==""||strings.TrimSpace(v.GetDonorId())==""||strings.TrimSpace(v.GetConnectionEpoch())==""||v.GetConnectionSequence()==0||v.GetCursor()==nil||strings.TrimSpace(v.GetCursor().GetJournalGeneration())==""||v.GetCursor().GetChannelOffset()==0||v.GetIdentityStatus()==collectorv1.IdentityStatus_IDENTITY_STATUS_UNSPECIFIED{return fmt.Errorf("required donation identity/domain field missing")};return nil}
